<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/ai.php';$admin=require_admin($pdo);$answer='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$question=trim((string)($_POST['question']??''));try{if($question==='')throw new RuntimeException('Ask a backend operations question.');$model=ai_setting_model_id($pdo,'admin');if(!$model)throw new RuntimeException('Configure an Admin default AI model first.');$context=[];
foreach(['users'=>'SELECT COUNT(*) FROM users','annotations'=>"SELECT COUNT(*) FROM annotations WHERE status='published'",'open_rights'=>"SELECT COUNT(*) FROM rights_claims WHERE status IN ('submitted','under_review')",'open_reports'=>"SELECT COUNT(*) FROM moderation_reports WHERE status IN ('open','under_review')",'queued_ai'=>"SELECT COUNT(*) FROM ai_jobs WHERE status='queued'",'failed_ai'=>"SELECT COUNT(*) FROM ai_jobs WHERE status='failed'",'queued_sources'=>"SELECT COUNT(*) FROM source_monitor_jobs WHERE status='queued'",'failed_sources'=>"SELECT COUNT(*) FROM source_monitor_jobs WHERE status='failed'"] as $k=>$sql){$context[$k]=(int)$pdo->query($sql)->fetchColumn();}
$changes=$pdo->query("SELECT s.public_id,s.domain,e.change_type,e.target_changed,e.diff_summary,e.created_at FROM source_change_events e JOIN sources s ON s.id=e.source_id ORDER BY e.created_at DESC LIMIT 12")->fetchAll();$failAi=$pdo->query("SELECT task_type,object_type,object_public_id,last_error,created_at FROM ai_jobs WHERE status='failed' ORDER BY created_at DESC LIMIT 8")->fetchAll();$failSources=$pdo->query("SELECT s.public_id,s.domain,j.last_error,j.created_at FROM source_monitor_jobs j JOIN sources s ON s.id=j.source_id WHERE j.status='failed' ORDER BY j.created_at DESC LIMIT 8")->fetchAll();
$payload=['counts'=>$context,'recent_source_changes'=>$changes,'recent_failed_ai_jobs'=>$failAi,'recent_failed_source_jobs'=>$failSources];$system='You are the Annotated system-admin operations assistant. Use only the sanitized operational context supplied. Prioritize actionable maintenance, queue health, source integrity, moderation workload, and AI reliability. Do not reveal secrets, infer claimant identity, make legal decisions, or take actions. Clearly separate observed system facts from recommendations.';$prompt="Admin question: $question\n\nSANITIZED SYSTEM CONTEXT:\n".json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);$r=ai_run($pdo,$config,$admin,'admin','admin_assistant',$model,$system,$prompt,[['type'=>'system_snapshot','counts'=>$context]],'admin','operations');$answer=$r['text'];}catch(RateLimitExceeded $e){$error=rate_limit_web_error($e);}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Assistant · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/admin/">Annotated Admin</a><nav><a href="/admin/ai.php">AI models</a><a href="/admin/source-monitor.php">Sources</a><a href="/admin/moderation.php">Moderation</a><a href="/admin/users.php">Users</a></nav></header><main class="panel article"><div class="pageTitle"><span class="eyebrow">ADMIN INTELLIGENCE</span><h1>Ask the backend</h1><p>The assistant receives a sanitized operational snapshot. It can analyze and recommend; it cannot perform admin actions.</p></div><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Question<textarea name="question" rows="5" required placeholder="What needs my attention right now?"></textarea></label><button>Ask admin AI</button></form><?php if($answer):?><div class="card aiAnswer"><span class="eyebrow">BACKEND BRIEF</span><p><?=nl2br(h($answer))?></p></div><?php endif?></main></body></html>
